import json
import re
from typing import List, Tuple, Set

def perceive(observation_history: list[str]) -> str:
    """
    Produce a concise text summary of decision-relevant features from the current raw observation.
    """
    try:
        raw = observation_history[-1]

        # Detect encoding type and parse grid
        if "<grid_" in raw:
            # ARC integer grid format
            grid = _parse_arc_grid(raw)
            color_names = {
                0: "black", 1: "blue", 2: "red", 3: "green", 4: "yellow",
                5: "light-gray", 6: "magenta", 7: "orange", 8: "light-blue",
                9: "maroon", 10: "white", 11: "dark-gray"
            }
        else:
            # Try JSON string grid format
            grid = _parse_json_grid(raw)
            if grid is None:
                return "(empty)"
            color_names = {}
            for r in grid:
                for c in r:
                    if c not in color_names:
                        color_names[c] = c

        if not grid or not grid[0]:
            return "(empty)"

        rows = len(grid)
        cols = len(grid[0])

        # Find dominant/background color
        color_counts = {}
        for r in range(rows):
            for c in range(cols):
                cell = grid[r][c]
                if isinstance(cell, int):
                    val = cell
                else:
                    val = cell
                color_counts[val] = color_counts.get(val, 0) + 1

        if not color_counts:
            return "(empty)"

        bg_color = max(color_counts, key=color_counts.get)

        # Collect non-background cells and their positions
        features = []
        for r in range(rows):
            for c in range(cols):
                cell = grid[r][c]
                if isinstance(cell, int):
                    val = cell
                    name = color_names.get(val, str(val))
                else:
                    val = cell
                    name = cell

                if val != bg_color:
                    features.append((r, c, name))

        # Also track "silver" (color 5/light-gray) and "brown" specially as they appear to be structural
        special_colors = {"silver", "brown", "light-gray", "magenta", "orange", "light-blue", "maroon", "white", "dark-gray"}

        # Build summary
        summary_parts = []

        # Grid dimensions
        summary_parts.append(f"grid={rows}x{cols}")

        # Background color
        bg_name = color_names.get(bg_color, str(bg_color)) if isinstance(bg_color, int) else bg_color
        summary_parts.append(f"bg={bg_name}")

        # Non-background cells (limit to keep under 2000 chars)
        if features:
            # Group by color for compactness
            by_color = {}
            for r, c, name in features:
                if name not in by_color:
                    by_color[name] = []
                by_color[name].append((r, c))

            color_summaries = []
            for color, positions in sorted(by_color.items()):
                if len(positions) <= 5:
                    pos_str = ";".join([f"({r},{c})" for r, c in positions])
                else:
                    pos_str = f"{len(positions)}cells"
                color_summaries.append(f"{color}:{pos_str}")

            summary_parts.append("nonbg=" + ",".join(color_summaries))

        # Detect and report "clickable" or interactive cells (silver/brown patterns)
        silver_cells = []
        brown_cells = []
        for r in range(rows):
            for c in range(cols):
                cell = grid[r][c]
                name = color_names.get(cell, str(cell)) if isinstance(cell, int) else cell
                if name in ("silver", "light-gray"):
                    silver_cells.append((r, c))
                elif name in ("brown", "maroon"):
                    brown_cells.append((r, c))

        if silver_cells:
            summary_parts.append(f"silver={len(silver_cells)}")
        if brown_cells:
            summary_parts.append(f"brown={len(brown_cells)}")

        # Look for changes from previous observation if available
        if len(observation_history) >= 2:
            prev_raw = observation_history[-2]
            prev_grid = None
            if "<grid_" in prev_raw:
                prev_grid = _parse_arc_grid(prev_raw)
            else:
                prev_grid = _parse_json_grid(prev_raw)

            if prev_grid and len(prev_grid) == rows and len(prev_grid[0]) == cols:
                changed_cells = []
                for r in range(rows):
                    for c in range(cols):
                        if grid[r][c] != prev_grid[r][c]:
                            old_name = color_names.get(prev_grid[r][c], str(prev_grid[r][c])) if isinstance(prev_grid[r][c], int) else prev_grid[r][c]
                            new_name = color_names.get(grid[r][c], str(grid[r][c])) if isinstance(grid[r][c], int) else grid[r][c]
                            changed_cells.append(f"({r},{c}):{old_name}->{new_name}")

                if changed_cells:
                    if len(changed_cells) <= 10:
                        summary_parts.append("changed=" + ";".join(changed_cells))
                    else:
                        summary_parts.append(f"changed={len(changed_cells)}cells")

        result = " | ".join(summary_parts)

        if not result:
            return "(empty)"

        if len(result) > 1900:
            # Truncate if needed
            result = result[:1900] + "..."

        return result

    except Exception:
        # Never raise, never return empty
        return "(empty)"


def _parse_arc_grid(raw: str) -> list:
    """Parse ARC integer grid format."""
    try:
        lines = raw.split('\n')
        in_grid = False
        grid = []

        for line in lines:
            stripped = line.strip()
            if '<grid_' in stripped:
                in_grid = True
                continue

            if in_grid:
                if stripped.startswith('[') and stripped.endswith(']'):
                    # Parse the row
                    row_str = stripped[1:-1].strip()
                    if row_str:
                        row = [int(x.strip()) for x in row_str.split(',')]
                        grid.append(row)
                elif not stripped or '=' in stripped or 'State:' in stripped or not stripped.startswith('['):
                    # End of grid section
                    if grid:
                        break

        return grid
    except Exception:
        return None


def _parse_json_grid(raw: str) -> list:
    """Parse JSON 2D array format."""
    try:
        # Find the JSON array
        s = raw.find('[[')
        if s == -1:
            return None

        # Find the matching closing brackets
        depth = 0
        e = s
        for i, ch in enumerate(raw[s:], s):
            if ch == '[':
                depth += 1
            elif ch == ']':
                depth -= 1
                if depth == 0:
                    e = i + 1
                    break

        if e <= s:
            return None

        json_str = raw[s:e]
        grid = json.loads(json_str)

        # Validate it's a 2D array
        if not isinstance(grid, list) or not grid or not isinstance(grid[0], list):
            return None

        return grid
    except Exception:
        return None

