        if not colour_counts:
            return f"step={step} | (empty)"
        bg_val = max(colour_counts, key=colour_counts.get)

        # ----- collect all non‑background cells with positions -----
        non_bg = {}   # colour_name -> list of (r,c)
        for r in range(rows):
