                    name = cell
                if val != bg_val:
                    non_bg.setdefault(name, []).append((r, c))

        # ----- build summary parts -----
        parts = [f"step={step}", f"grid={rows}x{cols}", f"bg={_name(bg_val, integer_color_names)}"]

        # list all non‑background colours with their positions
