            fallback_parts = [f"step={step}", f"grid={rows}x{cols}", f"bg={_name(bg_val, integer_color_names)}"]
            for colour, positions in sorted(non_bg.items()):
                fallback_parts.append(f"{colour}={len(positions)}")
            result = " | ".join(fallback_parts)

        if not result:
            return f"step={step} | (empty)"

        return result

    except Exception:
        return "(empty)"


