import json
from typing import List, Tuple

def perceive(observation_history: list[str]) -> str:
    """
    Produce a concise text summary of decision-relevant features from the current raw observation.
    Always includes coordinates for non-background cells to make actions recoverable.
    """
    try:
        raw = observation_history[-1]

        # Detect encoding type and parse grid
        if "<grid_" in raw:
            grid = _parse_arc_grid(raw)
            color_names = {
                0: "black", 1: "blue", 2: "red", 3: "green", 4: "yellow",
                5: "light-gray", 6: "magenta", 7: "orange", 8: "light-blue",
                9: "brown", 10: "white", 11: "dark-gray"
            }
        else:
            grid = _parse_json_grid(raw)
            if grid is None:
                return "grid=0x0"
            color_names = {}
            for r in grid:
                for c in r:
                    if c not in color_names:
                        color_names[c] = c

        if not grid or not grid[0]:
            return "grid=0x0"

        rows = len(grid)
        cols = len(grid[0])

        # Count all colors to find background
        color_counts = {}
        for r in range(rows):
            for c in range(cols):
                cell = grid[r][c]
                val = cell if isinstance(cell, int) else cell
                color_counts[val] = color_counts.get(val, 0) + 1

        if not color_counts:
            return "grid=0x0"

        bg_color = max(color_counts, key=color_counts.get)
        bg_name = color_names.get(bg_color, str(bg_color)) if isinstance(bg_color, int) else bg_color

        # Collect cells by color
        black_cells = []
        silver_cells = []
        brown_cells = []
        other_cells = []

        for r in range(rows):
            for c in range(cols):
                cell = grid[r][c]
                if isinstance(cell, int):
                    val = cell
                    name = color_names.get(val, str(val))
                else:
                    val = cell
                    name = cell

                if val == bg_color:
                    continue

                if name == "black":
                    black_cells.append((r, c))
                elif name in ("silver", "light-gray"):
                    silver_cells.append((r, c))
                elif name in ("brown", "maroon"):
                    brown_cells.append((r, c))
                else:
                    other_cells.append((r, c, name))

        # Sort all coordinate lists
        black_cells.sort()
        silver_cells.sort()
        brown_cells.sort()
        other_cells.sort(key=lambda x: (x[0], x[1]))

        # Build summary parts
        parts = [f"grid={rows}x{cols}", f"bg={bg_name}"]

        # Black cells
        if black_cells:
            black_str = ";".join([f"({r},{c})" for r, c in black_cells])
            if len(black_str) > 1500:  # If too long, use count
                parts.append(f"black={len(black_cells)}cells")
            else:
                parts.append(f"black={black_str}")
        else:
            parts.append("black=0")

        # Silver cells
        if silver_cells:
            silver_str = ";".join([f"({r},{c})" for r, c in silver_cells])
            if len(silver_str) > 1500:  # If too long, use count
                parts.append(f"silver={len(silver_cells)}cells")
            else:
                parts.append(f"silver={silver_str}")
        else:
            parts.append("silver=0")

        # Brown cells
        if brown_cells:
            brown_str = ";".join([f"({r},{c})" for r, c in brown_cells])
            if len(brown_str) > 1500:  # If too long, use count
                parts.append(f"brown={len(brown_cells)}cells")
            else:
                parts.append(f"brown={brown_str}")
        else:
            parts.append("brown=0")

        # Other non-background cells
        if other_cells:
            other_strs = []
            for r, c, name in other_cells[:20]:  # Limit to prevent blowup
                other_strs.append(f"{name}:({r},{c})")
            if len(other_cells) > 20:
                other_strs.append(f"...{len(other_cells)}total")
            parts.append("other=" + ";".join(other_strs))

        # Detect changes from previous state
        if len(observation_history) >= 2:
            prev_raw = observation_history[-2]
            prev_grid = None
            if "<grid_" in prev_raw:
                prev_grid = _parse_arc_grid(prev_raw)
            else:
                prev_grid = _parse_json_grid(prev_raw)

            if prev_grid and len(prev_grid) == rows and len(prev_grid[0]) == cols:
                changes = []
                for r in range(rows):
                    for c in range(cols):
                        if grid[r][c] != prev_grid[r][c]:
                            old = grid[r][c]
                            new = prev_grid[r][c]
                            old_name = color_names.get(old, str(old)) if isinstance(old, int) else old
                            new_name = color_names.get(new, str(new)) if isinstance(new, int) else new
                            changes.append(f"({r},{c}):{new_name}->{old_name}")

                if changes:
                    changes.sort()
                    change_str = ";".join(changes[:15])  # Limit changes
                    if len(changes) > 15:
                        change_str += f"...{len(changes)}total"
                    parts.append(f"delta={change_str}")

        result = " | ".join(parts)

        # Ensure result is not empty and under 2000 chars
        if not result:
            return "grid=0x0"

        if len(result) > 1900:
            result = result[:1900] + "..."

        return result

    except Exception:
        return "grid=0x0 | bg=unknown"


def _parse_arc_grid(raw: str) -> list:
    """Parse ARC integer grid format."""
    try:
        lines = raw.split('\n')
        in_grid = False
        grid = []

        for line in lines:
            stripped = line.strip()
            if '<grid_' in stripped:
                in_grid = True
                continue

            if in_grid:
                if stripped.startswith('[') and stripped.endswith(']'):
                    row_str = stripped[1:-1].strip()
                    if row_str:
                        row = [int(x.strip()) for x in row_str.split(',')]
                        grid.append(row)
                elif not stripped or '=' in stripped or 'State:' in stripped or not stripped.startswith('['):
                    if grid:
                        break

        return grid
    except Exception:
        return None


def _parse_json_grid(raw: str) -> list:
    """Parse JSON 2D array format."""
    try:
        s = raw.find('[[')
        if s == -1:
            return None

        depth = 0
        e = s
        for i, ch in enumerate(raw[s:], s):
            if ch == '[':
                depth += 1
            elif ch == ']':
                depth -= 1
                if depth == 0:
                    e = i + 1
                    break

        if e <= s:
            return None

        json_str = raw[s:e]
        grid = json.loads(json_str)

        if not isinstance(grid, list) or not grid or not isinstance(grid[0], list):
            return None

        return grid
    except Exception:
        return None

