def perceive(observation_history: list[str]) -> str:
    """
    Produce a concise text summary of decision-relevant features from the current raw observation.
    Output must be <2000 chars, never empty, never raise.
    """
    try:
        raw = observation_history[-1]

        # ---- 1. Parse grid (both integer and JSON formats) ----
        if "<grid_" in raw:
            grid = _parse_arc_grid(raw)
            color_map = {
                0: "black", 1: "blue", 2: "red", 3: "green", 4: "yellow",
                5: "light-gray", 6: "magenta", 7: "orange", 8: "light-blue",
                9: "maroon", 10: "white", 11: "dark-gray"
            }
        else:
            grid = _parse_json_grid(raw)
            if grid is None:
                return "(empty)"
            # Build a colour map that just maps each colour name to itself
            color_map = {}
            for row in grid:
                for cell in row:
                    if cell not in color_map:
                        color_map[cell] = cell

        if not grid or not grid[0]:
            return "(empty)"

        rows, cols = len(grid), len(grid[0])

        # ---- 2. Find background colour (most frequent) ----
        cell_counts = {}
        for r in range(rows):
            for c in range(cols):
                val = grid[r][c]
                cell_counts[val] = cell_counts.get(val, 0) + 1
        if not cell_counts:
            return "(empty)"
        bg_val = max(cell_counts, key=cell_counts.get)

        # ---- 3. Collect non‑background cells, grouped by colour ----
        groups = {}          # colour name -> list of (row, col)
        for r in range(rows):
            for c in range(cols):
                val = grid[r][c]
                if val == bg_val:
                    continue
                name = color_map.get(val, str(val))
                groups.setdefault(name, []).append((r, c))

        # ---- 4. Build the output string ----
        parts = [f"grid={rows}x{cols}"]
        bg_name = color_map.get(bg_val, str(bg_val))
        parts.append(f"bg={bg_name}")

        # Always list silver and brown explicitly by count if they exist
        # (they are the most important “action‑relevant” colours)
        # For all colours, we will attempt to list coordinates,
        # but we need to keep total length < 1900 characters.
        # We'll try to list all coordinates; if it would be too long,
        # we fall back to a compact representation.

        def colour_summary(name: str, cells: List[Tuple[int,int]]) -> str:
            """Return a compact string for one colour group."""
            if len(cells) <= 20:   # 20 cells ~ each coordinate 7 chars -> 140, safe
                return f"{name}:" + ";".join(f"({r},{c})" for (r,c) in sorted(cells))
            else:
                # Too many: show count and a few example positions
                sample = ";".join(f"({r},{c})" for (r,c) in sorted(cells)[:5])
                return f"{name}:{len(cells)}cells[{sample}]"

        colour_strs = []
        for name in sorted(groups.keys()):
            colour_strs.append(colour_summary(name, groups[name]))

        if colour_strs:
            parts.append("nonbg=" + ",".join(colour_strs))

        # ---- 5. Detect changes from previous observation (if available) ----
        if len(observation_history) >= 2:
            prev_raw = observation_history[-2]
            prev_grid = None
            if "<grid_" in prev_raw:
                prev_grid = _parse_arc_grid(prev_raw)
            else:
                prev_grid = _parse_json_grid(prev_raw)

            if prev_grid and len(prev_grid) == rows and len(prev_grid[0]) == cols:
                changed = []
                for r in range(rows):
                    for c in range(cols):
                        if grid[r][c] != prev_grid[r][c]:
                            old_val = prev_grid[r][c]
                            new_val = grid[r][c]
                            old_name = color_map.get(old_val, str(old_val))
                            new_name = color_map.get(new_val, str(new_val))
                            changed.append(f"({r},{c}):{old_name}->{new_name}")
                if changed:
                    if len(changed) <= 10:
                        parts.append("changed=" + ";".join(changed))
                    else:
                        parts.append(f"changed={len(changed)}cells")

        result = " | ".join(parts)

        # Ensure result is <2000 chars (safety)
        if len(result) > 1900:
            # Truncate, but keep the most important parts (grid, bg, silver/brown positions)
            # We'll just cut and add "..."
            result = result[:1900] + "..."
        if not result:
            result = "(empty)"
        return result

    except Exception:
        return "(empty)"


