import json
from typing import List

# Colour name to code mapping (0-11)
NAME_TO_CODE = {
    "black": 0, "blue": 1, "red": 2, "green": 3, "yellow": 4,
    "light-gray": 5, "silver": 5, "magenta": 6, "orange": 7,
    "light-blue": 8, "maroon": 9, "brown": 9, "white": 10, "dark-gray": 11
}
# Reverse mapping for output (compact code output uses integers)
# We keep integer output for compactness

def perceive(observation_history: list[str]) -> str:
    """
    Produce a concise text summary of the current grid.
    For grids with ≤ 100 cells, output the full grid as integer codes.
    For larger grids, output a compact non‑background summary.
    The output always contains all information needed to compute the next
    state when combined with an action.
    """
    try:
        raw = observation_history[-1]

        # 1. Parse grid into a list of lists of integers 0-11
        grid_codes = _parse_grid(raw)
        if grid_codes is None or not grid_codes or not grid_codes[0]:
            return "(empty)"

        rows = len(grid_codes)
        cols = len(grid_codes[0])
        total_cells = rows * cols

        # 2. If the grid is small enough, output the full integer grid
        if total_cells <= 100:
            # Represent each row as a comma‑separated list of ints
            rows_str = []
            for row in grid_codes:
                row_str = "[" + ",".join(str(c) for c in row) + "]"
                rows_str.append(row_str)
            data_str = "[" + ",".join(rows_str) + "]"
            return f"grid={rows}x{cols} | data={data_str}"

        # 3. For large grids, fall back to a non‑background summary
        # Count colours to find the most frequent (background)
        color_counts = {}
        for r in range(rows):
            for c in range(cols):
                val = grid_codes[r][c]
                color_counts[val] = color_counts.get(val, 0) + 1

        if not color_counts:
            return "(empty)"

        # Background = most common colour
        bg_code = max(color_counts, key=color_counts.get)
        bg_name = _code_to_name(bg_code)

        # Collect non‑background cells (code -> list of (r,c))
        nonbg = {}
        for r in range(rows):
            for c in range(cols):
                code = grid_codes[r][c]
                if code != bg_code:
                    nonbg.setdefault(code, []).append((r, c))

        parts = [f"grid={rows}x{cols}", f"bg={bg_name}"]

        if nonbg:
            color_strs = []
            for code, positions in sorted(nonbg.items()):
                color_name = _code_to_name(code)
                pos_list = ";".join(f"({r},{c})" for r, c in positions)
                if pos_list:
                    color_strs.append(f"{color_name}:{pos_list}")
            if color_strs:
                parts.append("nonbg=" + ",".join(color_strs))

        # Add some common colour counts for readability
        silver_count = len(nonbg.get(5, []))   # code 5 = silver/light-gray
        brown_count  = len(nonbg.get(9, []))   # code 9 = brown/maroon
        if silver_count:
            parts.append(f"silver={silver_count}")
        if brown_count:
            parts.append(f"brown={brown_count}")

        result = " | ".join(parts)
        if not result:
            return "(empty)"

        if len(result) > 1900:
            result = result[:1900] + "..."
        return result

    except Exception:
        return "(empty)"


def _parse_grid(raw: str) -> list:
    """Parse the raw observation into a list of lists of ints (0-11).
    Handles both ARC integer grid and JSON string grid encodings."""
    try:
        # Try JSON string grid first (fast)
        s = raw.find("[[")
        if s != -1:
            # Find matching ]] robustly
            depth = 0
            e = s
            for i, ch in enumerate(raw[s:], start=s):
                if ch == '[':
                    depth += 1
                elif ch == ']':
                    depth -= 1
                    if depth == 0:
                        e = i + 1
                        break
            if e > s:
                json_str = raw[s:e]
                parsed = json.loads(json_str)
                if isinstance(parsed, list) and len(parsed) > 0 and isinstance(parsed[0], list):
                    # Convert colour names to ints
                    int_grid = []
                    for row in parsed:
                        int_row = []
                        for cell in row:
                            cell_str = str(cell).lower()
                            code = NAME_TO_CODE.get(cell_str, 11)  # default dark-gray for unknown
                            int_row.append(code)
                        int_grid.append(int_row)
                    if int_grid and int_grid[0]:
                        return int_grid

        # Try ARC integer grid
        if "<grid_" in raw:
            lines = raw.split('\n')
            in_grid = False
            int_grid = []
            for line in lines:
                st = line.strip()
                if '<grid_' in st:
                    in_grid = True
                    continue
                if in_grid:
                    if st.startswith('[') and st.endswith(']'):
                        row_str = st[1:-1].strip()
                        if row_str:
                            row = [int(x.strip()) for x in row_str.split(',')]
                            int_grid.append(row)
                    elif not st or 'State:' in st or '=' in st or not st.startswith('['):
                        if int_grid:
                            break
            if int_grid:
                return int_grid

        return None
    except Exception:
        return None


def _code_to_name(code: int) -> str:
    """Map integer code to standard colour name (compatible with the palette)."""
    names = {
        0: "black", 1: "blue", 2: "red", 3: "green", 4: "yellow",
        5: "light-gray", 6: "magenta", 7: "orange", 8: "light-blue",
        9: "maroon", 10: "white", 11: "dark-gray"
    }
    return names.get(code, "gray")

