def _parse_header(raw: str) -> dict:
    """Extract step number, action count, and phase from the observation header."""
    info = {}
    try:
        for line in raw.split('\n'):
            line = line.strip()
            if line.startswith("Step:"):
                m = re.search(r'\d+', line)
                if m:
                    info['step'] = int(m.group())
            elif line.startswith("Action count:"):
                m = re.search(r'\d+', line)
                if m:
                    info['action_count'] = int(m.group())
            elif line.startswith("Phase:"):
                parts = line.split(":", 1)
                if len(parts) == 2:
                    info['phase'] = parts[1].strip()
        # If step not found, try to find a number after "Step "
        if 'step' not in info:
            for line in raw.split('\n'):
                if 'Step ' in line and ':' in line:
                    m = re.search(r'\d+', line)
                    if m:
                        info['step'] = int(m.group())
                        break
    except:
        pass
    return info


