                parsed = json.loads(json_str)
                if isinstance(parsed, list) and len(parsed) > 0 and isinstance(parsed[0], list):
                    int_grid = []
                    for row in parsed:
                        int_row = []
                        for cell in row:
                            cell_str = str(cell).lower()
                            code = NAME_TO_CODE.get(cell_str, 11)  # default dark-gray for unknown
                            int_row.append(code)
                        int_grid.append(int_row)
                    if int_grid and int_grid[0]:
                        return int_grid

        # Try ARC integer grid
        if "<grid_" in raw:
            lines = raw.split('\n')
