def perceive(observation_history: list[str]) -> str:
    """
    Produce a concise text summary of the current grid, including step/action count.
    For grids with ≤ 100 cells, output the full grid as integer codes.
    For larger grids, output a compact non‑background summary.
    The output always contains all information needed to compute the next
    state when combined with an action.
    """
    try:
        raw = observation_history[-1]

        # 1. Extract header information (step, action count, etc.)
        header = _parse_header(raw)
        step = header.get('step', '?')
        act_count = header.get('action_count', '?')
        # Build a prefix that changes even if grid does not
        prefix = f"step={step}|act={act_count}"

        # 2. Parse grid into a list of lists of integers 0-11
        grid_codes = _parse_grid(raw)
        if grid_codes is None or not grid_codes or not grid_codes[0]:
            return f"{prefix} | (empty)"

        rows = len(grid_codes)
        cols = len(grid_codes[0])
        total_cells = rows * cols

        # 3. If the grid is small enough, output the full integer grid
        if total_cells <= 100:
            rows_str = []
            for row in grid_codes:
                row_str = "[" + ",".join(str(c) for c in row) + "]"
                rows_str.append(row_str)
            data_str = "[" + ",".join(rows_str) + "]"
            return f"{prefix} | grid={rows}x{cols} | data={data_str}"

        # 4. For large grids, fall back to a non‑background summary
        color_counts = {}
        for r in range(rows):
            for c in range(cols):
                val = grid_codes[r][c]
                color_counts[val] = color_counts.get(val, 0) + 1

        if not color_counts:
            return f"{prefix} | (empty)"

        # Background = most common colour
        bg_code = max(color_counts, key=color_counts.get)
        bg_name = _code_to_name(bg_code)

        # Collect non‑background cells (code -> list of (r,c))
        nonbg = {}
        for r in range(rows):
            for c in range(cols):
                code = grid_codes[r][c]
                if code != bg_code:
                    nonbg.setdefault(code, []).append((r, c))

        parts = [prefix, f"grid={rows}x{cols}", f"bg={bg_name}"]

        if nonbg:
            color_strs = []
            for code, positions in sorted(nonbg.items()):
                color_name = _code_to_name(code)
                pos_list = ";".join(f"({r},{c})" for r, c in positions)
                if pos_list:
                    color_strs.append(f"{color_name}:{pos_list}")
            if color_strs:
                parts.append("nonbg=" + ",".join(color_strs))

        # Add some common colour counts for readability (optional)
        silver_count = len(nonbg.get(5, []))
        brown_count  = len(nonbg.get(9, []))
        if silver_count:
            parts.append(f"silver={silver_count}")
        if brown_count:
            parts.append(f"brown={brown_count}")

        result = " | ".join(parts)
        if not result:
            return f"{prefix} | (empty)"

        if len(result) > 1900:
            result = result[:1900] + "..."
        return result

    except Exception:
        # Never raise, never return empty
        return "step=?|act=? | (empty)"

import json
import re
from typing import List, Tuple, Optional

def perceive(observation_history: list[str]) -> str:
    """
    Produce a concise text summary of decision-relevant features from the current raw observation.
    Output must be <2000 chars, never empty, never raise.
    """
    try:
        raw = observation_history[-1]

        # ---- 1. Parse grid (both integer and JSON formats) ----
        if "<grid_" in raw:
            grid = _parse_arc_grid(raw)
            int_map = {
                0: "black", 1: "blue", 2: "red", 3: "green", 4: "yellow",
                5: "silver", 6: "magenta", 7: "orange", 8: "lightblue",
                9: "maroon", 10: "white", 11: "darkgray"
            }
            col_map = int_map
        else:
            grid = _parse_json_grid(raw)
            if grid is None:
                return "(empty)"
            col_map = None   # names are already strings

        if not grid or not grid[0]:
            return "(empty)"

        rows, cols = len(grid), len(grid[0])

        # ---- 2. Extract step number and action count from raw text ----
        step = _extract_int(raw, "Step:")
        action_count = _extract_int(raw, "Action count:")

        # ---- 3. Build a compact grid representation if grid is small ----
        total_cells = rows * cols
        compact_grid = None
        if total_cells <= 100:   # e.g. up to 10x10
            compact_grid = _compact_grid_str(grid, col_map)

        # ---- 4. Build the output string ----
        parts = [f"grid={rows}x{cols}"]
        if step is not None:
            parts.append(f"step={step}")
        if action_count is not None:
            parts.append(f"ac={action_count}")

        if compact_grid:
            # Full grid representation
            parts.append(f"grid_str={compact_grid}")
        else:
            # Fallback: list non‑background cells (original method)
            # Find background colour (most frequent)
            cell_counts = {}
            for r in range(rows):
                for c in range(cols):
                    val = grid[r][c]
                    cell_counts[val] = cell_counts.get(val, 0) + 1
            if not cell_counts:
                return "(empty)"
            bg_val = max(cell_counts, key=cell_counts.get)

            groups = {}
            for r in range(rows):
                for c in range(cols):
                    val = grid[r][c]
                    if val == bg_val:
                        continue
                    name = _colour_name(val, col_map)
                    groups.setdefault(name, []).append((r, c))

            bg_name = _colour_name(bg_val, col_map)
            parts.append(f"bg={bg_name}")

            def colour_summary(name: str, cells: List[Tuple[int,int]]) -> str:
                if len(cells) <= 20:
                    return f"{name}:" + ";".join(f"({r},{c})" for (r,c) in sorted(cells))
                else:
                    sample = ";".join(f"({r},{c})" for (r,c) in sorted(cells)[:5])
                    return f"{name}:{len(cells)}cells[{sample}]"

            colour_strs = []
            for name in sorted(groups.keys()):
                colour_strs.append(colour_summary(name, groups[name]))
            if colour_strs:
                parts.append("nonbg=" + ",".join(colour_strs))

        # ---- 5. Detect changes from previous observation (if available) ----
        if len(observation_history) >= 2:
            prev_raw = observation_history[-2]
            prev_grid = None
            if "<grid_" in prev_raw:
                prev_grid = _parse_arc_grid(prev_raw)
            else:
                prev_grid = _parse_json_grid(prev_raw)

            if prev_grid and len(prev_grid) == rows and len(prev_grid[0]) == cols:
                changed = []
                for r in range(rows):
                    for c in range(cols):
                        if grid[r][c] != prev_grid[r][c]:
                            old_val = prev_grid[r][c]
                            new_val = grid[r][c]
                            old_name = _colour_name(old_val, col_map)
                            new_name = _colour_name(new_val, col_map)
                            changed.append(f"({r},{c}):{old_name}->{new_name}")
                if changed:
                    if len(changed) <= 10:
                        parts.append("changed=" + ";".join(changed))
                    else:
                        parts.append(f"changed={len(changed)}cells")

        result = " | ".join(parts)

        # Ensure result is <2000 chars
        if len(result) > 1900:
            # Truncate, but keep the most important parts (grid, step, ac, grid_str)
            # We'll cut and add "..."
            result = result[:1900] + "..."
        if not result:
            result = "(empty)"
        return result

    except Exception:
        return "(empty)"


# ----------------------------------------------------------------------
# Helper functions
# ----------------------------------------------------------------------

def _colour_name(val, col_map):
    """Return a short single‑letter colour string for the given cell value."""
    if col_map is None:
        # val is a colour name string
        return _abbrev_name(val)
    else:
        # val is an integer
        name = col_map.get(val)
        if name is None:
            return str(val)
        return _abbrev_name(name)

def _abbrev_name(name: str) -> str:
    """Map colour name to a single character."""
    mapping = {
        "black": "k",
        "blue": "u",
        "red": "r",
        "green": "g",
        "yellow": "y",
        "silver": "s",
        "magenta": "m",
        "orange": "o",
        "lightblue": "l",
        "maroon": "a",
        "white": "w",
        "darkgray": "d",
        "light-gray": "s",   # silver
        "light-blue": "l",
        "dark-red": "a",
        "dark-gray": "d",
        "gold": "y",         # map gold to yellow
        "darkgreen": "g",
        "gray": "d",
        "brown": "b",        # brown appears in examples
    }
    return mapping.get(name.lower(), name[0] if name else "?")

def _compact_grid_str(grid, col_map) -> str:
    """Return a compact string representation of the whole grid."""
    rows = []
    for row in grid:
        row_str = "".join(_colour_name(cell, col_map) for cell in row)
        rows.append(row_str)
    return "/".join(rows)   # rows separated by '/'

def _extract_int(raw: str, key: str) -> Optional[int]:
    """Extract the first integer after the given key in the raw string."""
    try:
        # Find key followed by whitespace and digits
        idx = raw.find(key)
        if idx == -1:
            return None
        rest = raw[idx+len(key):]
        # Skip whitespace and punctuation
        match = re.search(r'[-]?\d+', rest)
        if match:
            return int(match.group())
        return None
    except:
        return None

def _parse_arc_grid(raw: str) -> Optional[list]:
    """Parse ARC integer grid format. Returns list of rows (list of ints)."""
    try:
        lines = raw.split('\n')
        in_grid = False
        grid = []
        for line in lines:
            stripped = line.strip()
            if '<grid_' in stripped:
                in_grid = True
                continue
            if in_grid:
                if stripped.startswith('[') and stripped.endswith(']'):
                    row_str = stripped[1:-1].strip()
                    if row_str:
                        row = [int(x.strip()) for x in row_str.split(',')]
                        grid.append(row)
                elif not stripped or '=' in stripped or 'State:' in stripped:
                    if grid:
                        break
        return grid if grid else None
    except Exception:
        return None

def _parse_json_grid(raw: str) -> Optional[list]:
    """Parse JSON 2D array format. Returns list of rows (list of strings)."""
    try:
        s = raw.find('[[')
        if s == -1:
            return None
        depth = 0
        e = s
        for i, ch in enumerate(raw[s:], s):
            if ch == '[':
                depth += 1
            elif ch == ']':
                depth -= 1
                if depth == 0:
                    e = i + 1
                    break
        if e <= s:
            return None
        json_str = raw[s:e]
        grid = json.loads(json_str)
        if not isinstance(grid, list) or not grid or not isinstance(grid[0], list):
            return None
        # Convert to lowercase names (they might already be)
        grid_clean = [[cell.lower() for cell in row] for row in grid]
        return grid_clean
    except Exception:
        return None

