            }
        else:
            grid = _parse_json_grid(raw)
            if grid is None:
                return "(empty)"
            # Build a colour map that just maps each colour name to itself
            color_map = {}
            for row in grid:
                for cell in row:
                    if cell not in color_map:
                        color_map[cell] = cell

        if not grid or not grid[0]:
            return "(empty)"

        rows, cols = len(grid), len(grid[0])

        # ---- 2. Find background colour (most frequent) ----
        cell_counts = {}
        for r in range(rows):
            for c in range(cols):
                val = grid[r][c]
                cell_counts[val] = cell_counts.get(val, 0) + 1
        if not cell_counts:
            return "(empty)"
        bg_val = max(cell_counts, key=cell_counts.get)

        # ---- 3. Collect non‑background cells, grouped by colour ----
        groups = {}          # colour value -> list of (row, col)
        for r in range(rows):
            for c in range(cols):
                val = grid[r][c]
                if val == bg_val:
                    continue
                groups.setdefault(val, []).append((r, c))

        # ---- 4. Build the output string ----
        parts = [f"grid={rows}x{cols}"]
        bg_name = color_map.get(bg_val, str(bg_val))
