        black_val = None
        for val in groups:
            name = color_map.get(val, str(val))
            if name == "black" or val == 0 or val == "black":
                black_val = val
                break

        # Collect non-background cells by colour name for output
        colour_cells = {}
        for val, cells in groups.items():
            name = color_map.get(val, str(val))
            colour_cells[name] = cells

        # Create compact representation for each colour group
        def colour_summary(name: str, cells: List[Tuple[int,int]]) -> str:
            """Return a compact string for one colour group."""
            if len(cells) <= 25:
                return f"{name}:" + ";".join(f"({r},{c})" for r, c in sorted(cells))
            else:
