        # Clickable cells (black cells that can be clicked)
        clickable = colour_cells.get("black", [])
        if black_val and black_val != "black":
            clickable = colour_cells.get(str(black_val), [])
        if clickable:
            # Limit to avoid exceeding char limit
            if len(clickable) <= 15:
                parts.append("clickable=" + ";".join(f"({r},{c})" for r, c in clickable))
            else:
                parts.append(f"clickable={len(clickable)}cells")
        else:
            parts.append("clickable=none")

        # Silver cells (if any) - these move downward on noop
        silver_cells = colour_cells.get("silver", [])
        if silver_cells:
            silver_str = ";".join(f"({r},{c})" for r, c in sorted(silver_cells))
            parts.append(f"silver={silver_str}")

        # Brown cells - indicate they are not clickable (distinguish from clickable black)
        brown_cells = colour_cells.get("brown", [])
        if brown_cells:
            if len(brown_cells) <= 15:
                parts.append(f"brown=" + ";".join(f"({r},{c})" for r, c in brown_cells))
            else:
                parts.append(f"brown={len(brown_cells)}cells")

        # ---- 6. Detect changes from previous observation (if available) ----
        if len(observation_history) >= 2:
            prev_raw = observation_history[-2]
            prev_grid = None
            if "<grid_" in prev_raw:
                prev_grid = _parse_arc_grid(prev_raw)
            else:
                prev_grid = _parse_json_grid(prev_raw)

            if prev_grid and len(prev_grid) == rows and len(prev_grid[0]) == cols:
                changed = []
                for r in range(rows):
                    for c in range(cols):
                        if grid[r][c] != prev_grid[r][c]:
                            old_val = prev_grid[r][c]
                            new_val = grid[r][c]
                            old_name = color_map.get(old_val, str(old_val))
                            new_name = color_map.get(new_val, str(new_val))
                            changed.append(f"({r},{c}):{old_name}->{new_name}")
                if changed:
                    # Sort for consistency
                    changed.sort(key=lambda x: (int(x.split(",")[0][1:]), int(x.split(",")[1])))
                    if len(changed) <= 12:
                        parts.append("changed=" + ";".join(changed))
                    else:
                        # Just report count and first/last few
                        first_few = ";".join(changed[:5])
                        parts.append(f"changed={len(changed)}cells[{first_few}]")

        result = " | ".join(parts)

        # Ensure result is <2000 chars
        if len(result) > 1900:
            # Truncate, but keep structural info
            result = result[:1900] + "..."
        if not result:
            result = "(empty)"
        return result

    except Exception:
        return "(empty)"


