    """
    try:
        raw = observation_history[-1]

        # ---- 1. Parse grid (both integer and JSON formats) ----
        if "<grid_" in raw:
            grid = _parse_arc_grid(raw)
            # For integer grids use the mapping; note that "silver" is not in the standard palette,
            # but we treat light‑gray (5) as silver if it appears (rare).
            color_name = {
                0: "black", 1: "blue", 2: "red", 3: "green", 4: "yellow",
                5: "light-gray", 6: "magenta", 7: "orange", 8: "light-blue",
                9: "maroon", 10: "white", 11: "dark-gray"
            }
        else:
            grid = _parse_json_grid(raw)
            if grid is None:
                return "(empty)"
            color_name = None  # we'll use the string value directly

        if not grid or not grid[0]:
            return "(empty)"

        rows, cols = len(grid), len(grid[0])

        # ---- 2. Canonicalise cells and find background ----
        canonical_grid = []
        cell_counts = {}
        for r in range(rows):
            row = []
            for c in range(cols):
                if color_name is not None:
                    val = grid[r][c]
                    name = color_name.get(val, str(val))
                else:
                    name = grid[r][c]  # already a string
                row.append(name)
                cell_counts[name] = cell_counts.get(name, 0) + 1
            canonical_grid.append(row)

        if not cell_counts:
            return "(empty)"
        bg_val = max(cell_counts, key=cell_counts.get)

        # ---- 3. Collect non‑background cells, separated by colour ----
        groups = {}          # colour name -> list of (row, col)
        black_cells = []
        silver_cells = []
        for r in range(rows):
            for c in range(cols):
                name = canonical_grid[r][c]
                if name == bg_val:
                    continue
                groups.setdefault(name, []).append((r, c))
                if name == "black":
                    black_cells.append((r, c))
                elif name == "silver":
                    silver_cells.append((r, c))

        # ---- 4. Build the output string ----
        parts = [f"grid={rows}x{cols}"]
        parts.append(f"bg={bg_val}")

        # ---- 4a. List all non‑background cells, sorted ----
        def colour_summary(name: str, cells: List[Tuple[int,int]]) -> str:
            if len(cells) <= 20:
                return f"{name}:" + ";".join(f"({r},{c})" for (r,c) in sorted(cells))
            else:
                sample = ";".join(f"({r},{c})" for (r,c) in sorted(cells)[:5])
                return f"{name}:{len(cells)}cells[{sample}]"

        colour_strs = [colour_summary(name, groups[name]) for name in sorted(groups.keys())]
        if colour_strs:
            parts.append("nonbg=" + ",".join(colour_strs))

        # ---- 4b. Add dynamic hints for forward prediction ----
        # Silver movement on noop (if any silver exists)
        if silver_cells:
            silver_next = []
            for (r, c) in silver_cells:
                if r + 1 < rows and canonical_grid[r+1][c] != "brown":
                    silver_next.append((r+1, c))
                else:
                    silver_next.append((r, c))
            # Only output if the list is different from current (to save space)
            if sorted(silver_next) != sorted(silver_cells):
                next_str = ";".join(f"({r},{c})" for (r,c) in sorted(silver_next))
                parts.append(f"silver_next={next_str}")

        # Constant rule for click actions
        parts.append("rule:click black->silver")

        # ---- 4c. Detect changes from previous observation (optional) ----
        if len(observation_history) >= 2:
            prev_raw = observation_history[-2]
            prev_grid = _parse_arc_grid(prev_raw) if "<grid_" in prev_raw else _parse_json_grid(prev_raw)
            if prev_grid and len(prev_grid) == rows and len(prev_grid[0]) == cols:
                changed = []
                for r in range(rows):
                    for c in range(cols):
                        cur = canonical_grid[r][c]
                        prev = prev_grid[r][c]
                        if color_name is not None:
                            prev = color_name.get(prev, str(prev))
                        if cur != prev:
                            changed.append(f"({r},{c}):{prev}->{cur}")
                if changed:
                    if len(changed) <= 10:
                        parts.append("changed=" + ";".join(changed))
                    else:
                        parts.append(f"changed={len(changed)}cells")

        result = " | ".join(parts)

        # ---- 5. Enforce length < 2000 chars ----
        if len(result) > 1900:
            result = result[:1900] + "..."
        if not result:
            result = "(empty)"
        return result

    except Exception:
        return "(empty)"


# ----------------------------------------------------------------------
# Helper parsers (unchanged, except minor robustness)
# ----------------------------------------------------------------------

def _parse_arc_grid(raw: str) -> Optional[list]:
    """Parse ARC integer grid format. Returns list of rows (list of ints)."""
    try:
        lines = raw.split('\n')
        in_grid = False
        grid = []
        for line in lines:
            stripped = line.strip()
            if '<grid_' in stripped:
                in_grid = True
                continue
            if in_grid:
                if stripped.startswith('[') and stripped.endswith(']'):
                    row_str = stripped[1:-1].strip()
                    if row_str:
                        row = [int(x.strip()) for x in row_str.split(',')]
                        grid.append(row)
                elif not stripped or '=' in stripped or 'State:' in stripped:
                    if grid:
                        break
        return grid if grid else None
    except Exception:
        return None


def _parse_json_grid(raw: str) -> Optional[list]:
    """Parse JSON 2D array format. Returns list of rows (list of strings)."""
    try:
        s = raw.find('[[')
        if s == -1:
            return None
        depth = 0
        e = s
        for i, ch in enumerate(raw[s:], s):
            if ch == '[':
                depth += 1
            elif ch == ']':
                depth -= 1
                if depth == 0:
                    e = i + 1
                    break
        if e <= s:
            return None
        json_str = raw[s:e]
        grid = json.loads(json_str)
        if not isinstance(grid, list) or not grid or not isinstance(grid[0], list):
            return None
        return grid
    except Exception:
        return None
